/**
 * Demo build constants.
 *
 * This copy of the platform runs with no Supabase project and no hosted
 * database: Postgres is PGlite (scripts/demo-db.mts), sign-in is a cookie
 * holding the demo user's id, and file storage is a folder on disk. Every
 * record is generated by prisma/demo-seed.ts -- none of it is real.
 */

/** Cookie holding the signed-in demo user's authUserId. */
export const DEMO_AUTH_COOKIE = "demo_uid";

/** Pre-filled on the login screen. Any password is accepted. */
export const DEMO_LOGIN_EMAIL = "owner@demo.securetecc.example";

/** Where demo "storage buckets" live on disk. */
export const DEMO_STORAGE_DIR = "demo-data/storage";
